// Package codegen generates the route registration code consumed by the
// server. Generated files are build artifacts — never hand-edited, never
// committed. Generation happens at build time only; the production request
// path executes plain pre-registered Go routes with no scanning,
// reflection, or Node involvement.
package codegen

import (
	"fmt"
	"go/format"
	"os"
	"path/filepath"
	"strings"

	"go-meta/internal/routing"
)

// header is stamped on every generated file.
const header = "// Code generated by go-meta route generator. DO NOT EDIT."

// RoutesFile generates the Go source of the routes registration package
// for the discovered route set. Output is deterministic for identical
// inputs: routes are emitted in manifest (path-sorted) order and passed
// through go/format, so bytes are stable across runs.
func RoutesFile(m routing.Manifest) ([]byte, error) {
	var b strings.Builder
	b.WriteString(header)
	b.WriteString("\n\npackage routes\n\n")

	// The import set is fixed for this generator version, so ordering is
	// trivially deterministic.
	b.WriteString("import (\n")
	b.WriteString("\t\"go-meta/internal/routing\"\n")
	b.WriteString(")\n\n")

	b.WriteString("// RegisterRoutes is generated from the app tree at build time.\n")
	b.WriteString("func RegisterRoutes() []routing.Route {\n")
	b.WriteString("\treturn []routing.Route{\n")
	for _, r := range m.Routes {
		writeRouteLiteral(&b, r)
	}
	b.WriteString("\t}\n}\n")

	formatted, err := format.Source([]byte(b.String()))
	if err != nil {
		// The generator itself produced invalid Go — always a bug here,
		// never a user-input condition.
		return nil, fmt.Errorf("codegen: generated source does not format (generator bug): %w", err)
	}
	return formatted, nil
}

func writeRouteLiteral(b *strings.Builder, r routing.Route) {
	fmt.Fprintf(b, "\t\t{ID: %q, Path: %q, SourceFile: %q, Mode: %q",
		r.ID, r.Path, r.SourceFile, r.Mode)
	if len(r.Layouts) == 0 {
		b.WriteString("},\n")
		return
	}
	b.WriteString(", Layouts: []routing.Layout{\n")
	for _, l := range r.Layouts {
		fmt.Fprintf(b, "\t\t\t{ID: %q, SourceFile: %q, Mode: %q},\n",
			l.ID, l.SourceFile, l.Mode)
	}
	b.WriteString("\t\t}},\n")
}

// WriteRoutesFile generates and writes generated/routes_gen.go beneath dir.
// The caller passes the repo root; the output path is fixed by the
// generator, matching the blueprint's artifact location.
func WriteRoutesFile(dir string, m routing.Manifest) error {
	src, err := RoutesFile(m)
	if err != nil {
		return err
	}
	dst := filepath.Join(dir, "generated", "routes_gen.go")
	if err := os.MkdirAll(filepath.Dir(dst), 0o755); err != nil {
		return fmt.Errorf("codegen: create generated directory: %w", err)
	}
	if err := os.WriteFile(dst, src, 0o644); err != nil {
		return fmt.Errorf("codegen: write %s: %w", dst, err)
	}
	return nil
}
